-- --------------------------------------------------------
-- 6. Tabel `monitoring_logs` (Pre-seeded for 30-day SLA Calculation BUG-011)
-- --------------------------------------------------------
CREATE TABLE `monitoring_logs` (
  `log_id` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`log_id`),
  `asset_id` int(11) NOT NULL,
  `check_time` datetime NOT NULL,
  `status` enum('unknown','online','offline','error','warning') NOT NULL DEFAULT 'unknown',
  `method` varchar(20) DEFAULT NULL,
  `source` varchar(20) DEFAULT 'monitoring_engine',
  `response_time_ms` int(11) NOT NULL,
  `details` text NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Dumping data untuk tabel `monitoring_logs`
